    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))
    return comps

def _shape(cells):
    r0 = min(r for r,c in cells)
    c0 = min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    # When two separate objects have the same exact silhouette, harmonize
    # the later one to the color of the first (top-to-bottom, left-to-right).
    comps.sort(key=lambda item: min(item[1]))
    first_by_shape = {}
